# ── data loading ──────────────────────────────────────────────────────────

def load_results(path: str) -> Dict[str, Any]:
    fpath = os.path.join(path, "profiling_results.json")
    if not os.path.exists(fpath):
        print(f"[WARN] Not found: {fpath}")
        return {}
    with open(fpath) as f:
        return json.load(f)


def merge_importance_runs(dirs: List[str]) -> Dict[str, Any]:
    """Merge multiple single-sparsity importance runs into one unified dict."""
    merged_ii: Dict[str, Dict[str, Any]] = {}
    merged_ppl: Dict[str, Dict[str, Any]] = {}
    merged_config = {}
    merged_phase_stats = {}

    for d in dirs:
        data = load_results(d)
        if not data:
            continue
        merged_config = data.get("config", merged_config)
        merged_phase_stats = data.get("phase_stats", merged_phase_stats)

        for phase, levels in data.get("interaction_index", {}).items():
            merged_ii.setdefault(phase, {}).update(levels)
